import Link from "next/link";
import { productServices } from "@/lib/content";

const PORTFOLIO_ITEMS = [
  {
    href: "/number",
    title: "数字生命",
    img: productServices[0].image,
  },
  {
    href: "/name",
    title: "姓名学",
    img: productServices[1].image,
  },
  {
    href: "/tarot",
    title: "塔罗占卜",
    img: productServices[2].image,
  },
  {
    href: "/eastern-divination",
    title: "东方占卜术",
    img: productServices[3].image,
  },
];

export function ProductServicesSection() {
  return (
    <>
      <section className="page-hero portfolio-hero">
        <h1>产品服务</h1>
      </section>
      <section className="portfolio">
        <div className="portfolio-grid">
          {PORTFOLIO_ITEMS.map((item) => (
            <Link key={item.href} href={item.href} className="portfolio-card">
              <h2>{item.title}</h2>
              <span className="portfolio-card-media">
                <img src={item.img} alt="" />
              </span>
            </Link>
          ))}
        </div>
      </section>
    </>
  );
}
